import{_ as e,c as r,o as h,af as p}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易尚氏學 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易尚氏學 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"classics/shangshi/006.md","filePath":"classics/shangshi/006.md"}'),i={name:"classics/shangshi/006.md"};function l(n,a,d,s,t,c){return h(),r("div",null,[...a[0]||(a[0]=[p('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>說卦乾健也。於夏傳元始也。亨通也。利和也。貞正也。蓋天之體以健為用。而天之德莫大於四時。元亨利貞。即春夏秋冬。即東南西北。震元離亨兌利坎貞。往來循環。不忒不窮。周易之名。即以此也。後儒釋此者。莫過於太玄。玄文雲。罔直蒙酋冥。罔北方也。冬也。未有形也。直東方也。春也。直而未有文也。蒙南方也。夏出。物之修長也。酋西方也。秋也。物皆成象而就也。有形則復於無形。故曰冥。故萬物罔乎北。直乎東。蒙乎南。酋乎西。冥乎北。罔舍其氣。直觸其類。蒙極其修。酋考其就。冥反其奧。罔蒙相極。直酋相敕。出冥入冥。新故代更。將來者進。成功者退。已用則賤。當時則貴。按大玄闡發此四字之理。至矣盡矣。除彖傳外。無此深奧明晰之解釋也。其所謂直蒙酋。即震春離夏兌秋。即元亨利也。所謂罔冥。即坎冬。即貞也。必以二字擬貞者。蓋以子復為界。子復者冬至也。故由亥坤至子復為冥。由子復至泰寅為罔。罔不直也。冬至以後。萬物雖枉屈。不能見形於外。然陽氣已生。與冬至前之冥然罔覺者異矣。故曰罔舍其氣。舍者蓄也。養也。即彖傳所謂保合太和也。或曰彖傳釋此。純指天道。然彖不曰春夏秋冬。必曰元亨利貞者何也。曰乾之德無所不統。無所不包。言元亨利貞。則天時人事。盡括於其中。</p><p>惟此四字。義蘊宏深。非一解所能盡。彖傳象傳。皆釋貞為正。而大貞。小貞。不可貞。貞吝。貞兇。不利君子貞。義皆不通。而彖象傳遇此皆不釋。似委為不知而闕疑者。文言曰。貞固足以乾事。又釋貞為固。然於貞兇貞吝等辭。仍不能通。此彖象傳與文言不同也。</p><p>尤異者。乾彖傳以萬物資始釋元義。以雲行雨施品物流形釋亨義。以大明終始六位時成釋利義。以天道變化各正性命釋貞義。是以四德平列也。而於屯隨之元亨利貞。則釋曰大亨貞。於臨無妄革之元亨利貞。則釋曰大亨以正。舍利不言。祇為二德。是彖傳與彖傳。所釋不同也。文言曰元者善之長。亨者嘉之會。利者義之和。貞者事之乾。是以四德平列。尤為顯著。乃下又曰乾元者始而亨者也。利貞者性情也。則以元亨為一義。利貞為一義。亦為二德。此又文言與文言所釋不同也。昔儒以彖象傳釋貞字。與文言不同。疑十翼非出一手。愚謂彖傳當為一人作矣。而前後所釋不同。文言當為一人作矣。而前後所詁仍異。此無他。乾健之德。不可名言。似必再三釋。方能畢其義蘊也。</p><p>然則元亨利貞四字。究以何解為當乎。曰其在乾則確為四德。彖傳之所釋。宏深透闢。於四德各有推闡。而以天道變化。各正性命。保合大和。釋貞之原理。尤幽隱難識。故文言曰。君子行此四德。蓋四德缺一。即不成為天時。不成為人事。故太玄以罔直蒙酋冥擬之。並著其義曰春夏秋冬。指其方曰東西南北。則亦以元亨利貞為四德也。</p><p>至於貞吝貞兇。不利君子貞。其義與乾元亨利貞之貞。絕不相同。案周禮春官。天府季冬陳玉。貞來歲之媺惡。注貞謂問於龜卜。鄭司農曰。貞問也。易曰。師貞丈人吉。又左傳哀十七年。衛侯貞卜。國語貞於陽卜。皆以貞為卜問。而師貞丈人吉。前鄭引以解周禮。是以貞為卜問。已有先例。愚以為大貞小貞貞吝貞兇不利君子貞。皆宜詁作卜問。與乾元亨利貞之貞。判然為二義。不得混同。五經字同而義異者多矣。不獨此也。蓋貞有正義。又有貞固貞定二義。朱子兼採之。曰貞正而固也。豈知兼二義。仍不能盡通。近儒王陶廬先生又以全易貞字皆釋作卜問。於文理可通矣。然若乾之利貞。亦釋作卜問。則乾德不全矣。似不盡協也。</p><p>蓋元亨利貞。合之為乾德。分之為八卦之德。故即為六十四卦之根本。象或曰亨。或曰元亨。或曰貞。或曰利貞。或曰亨利貞。或曰利貞亨。或曰元亨利貞。似以此四德。為衡量卦德之準的者。然如無妄兇卦也。亦曰元亨利貞。則似別有標識。而非論卦德。端木國瑚曰。易遇東南方春夏之卦。則曰元亨。遇西北方秋冬之卦。則曰利貞。由其言推之。屯下震春也。故曰元亨。上坎冬也。故曰利貞。隨下震春也。故曰元亨。上兌秋也。故曰利貞。臨下互震故曰元亨。上坤下兌。故曰利貞。無妄下震故曰元亨。上乾為冬。故曰利貞。革下離互巽。故曰元亨。上兌為秋。互乾為冬。故曰利貞。其餘雖不盡當。然大概如是也。總之元亨利貞。春夏秋冬。東南西北。仁義禮智。一二三四。茲數者。合之一之。混之同之。融會貫通。遺貌御神。天人不分。陶冶既久。然後知此四字。已括盡易理。非言詮所能盡。而能申其義者。前惟彖傳。後惟楊子云。</p><p>彖曰。大哉乾元。萬物資始。乃統天。雲行雨施。品物流形。大明終始。六位時成。時乘六龍以御天。乾道變化。各正性命。保合太和。乃利貞。首出庶物。萬國咸寧。</p><p>繫辭雲。彖者材也。材財通。孟子有達財者。而財與裁通。泰傳後以財成天地之道。漢人上書。伏惟裁察。每作財察。然則材即斷也。即裁度也。元亨利貞者。彖辭也。此則釋彖者。先儒名曰彖傳。十翼之一也。自太史公楊子云班固。皆以為孔子作。乾元者。乾之元氣也。於時配春。故曰資始。統說文紀也。史記樂書樂統同。注統領也。統天者。言乾元之德統領萬物。總治一切。九家釋統為繼。謂乾德統繼天道。後諸家又有訓統為始為本為合者。皆非也。按此釋元義。</p><p>「雲行雨施。品物流形」此釋亨義。於時配夏。乾交坤成坎。坎為云為雨。故曰云行而施。坤為品物。乾入坤。故曰流形。乾施坤受。和而為雨。品物潤澤。萬物潔齊。相見乎離。亨之義也。</p><p>「大明終始。六位時成。時乘六龍以御天」此釋利義。於時配秋。乾為日。故曰大明。日始於離。終於坎。以成晝夜。積晝夜以成四時。六位者六爻。爻各有時。時而至秋。萬物成熟。故曰時成。太玄擬之曰酋西方也。秋也。萬物皆成象而就。釋時成之義也。文言曰。利義之和也。兌正秋。兌悅故和。秋成故利也。然乾之六時。果何屬乎。六龍者六陽。乾陽卦。故其所乘之時皆陽時。即子寅辰午申戌。乾鑿度所謂乾貞十一月子。左行陽時六是也。言乾而乾三子可知。若坤之所乘。則六陰時。乾鑿度所謂坤貞六月未。右行陰時六是也。時乘六龍以御天。即言乾乘六陽時以統御天道。自漢以來。不知時乘六龍。即乾乘六陽時。籠統解說。與上句六位時成無以異。而傳義愈晦矣。</p><p>「乾道變化。各正性命。保合太和。乃利貞。」此釋貞義。於時為冬。萬物自有而入無。由動而之靜。故曰變化。太玄擬貞為冥。曰有形則復於無形。故曰冥。又曰冥者明之藏也。出冥入冥。新故代更。人冥者變。出冥者變後而化也。變化者天道必然之理也。性命者精神。太和者元氣。正者定也。周禮天官。宰夫令群吏正歲會。正月要。注正定也。各正性命者。言萬物入冬而形氣定也。保合者固也。保合太和。言萬物靜定而無為。正所以養育其生命也。各正性命。保合太和。略如人人夜寢息。休養神明。繫辭雲。尺蠖之屈。以求信也。龍蛇之蟄。以存身也。精義入神。以致用也。正謂此也。貞者元之本。元者貞之著。下文曰首出庶物。即貞下啟元之義也。後儒舍冬義。以既濟定說貞者。皆未當也。</p><p>「首出庶物。萬國咸寧。」元亨利貞。相循環者也。貞非寂滅無為也。乃所以植元亨之基。故夫冬盡春來。貞久元至。首出庶物者。元也。言又復始也。春生震仁。故曰咸寧。萬國咸寧者。言如聖君當陽首出。萬邦有慶也。</p><p>乾彖傳簡括宏深。自非聖於易者。不能為也。自漢以來。除太玄外。無有明其義者。而詁六龍為六位。利貞為既濟定。尤謬誤之大者。首出庶物二語。解者皆不誤矣。而皆不知於元亨利貞之後。再綴此語者。乃所以示四德循環之義。朱子雲。不貞則無以為元。又曰四德循環無端。知此義矣。乃訖未明指再綴此語之故。豈知六龍與六位無別。則六龍句為贅語。首出庶物。與萬物資始理同。而不疏其循環之義。則首出句又為贅語。烏乎可哉。揆厥原因。皆由不確知元亨利貞。即春夏秋冬。即東南西北。彖傳與文言雖未明言，固皆本此為義。特義奧語文。後儒遂歧於索解。及楊子云揭出春夏秋冬。東南西北二義。然後知彖傳所言者。皆元亨利貞之原理。及其所以然。義遂明徹。然罔直蒙酋冥之演元亨利貞。除範望司馬溫公外。他儒無言者。於以知太玄之難讀。等於易也。</p><p>象日。天行健。君子以自強不息。</p><p>繫辭雲。象者像也。像此者也。先儒以其推闡一卦之義謂為大象。亦十翼之一。王引之雲。爾雅行道也。天行健。謂天道健也。與地勢順為對文。按左傳襄九年。晉伐鄭。杞人從趙武斬行栗。注行道也。由是以推。蠱剝復彖傳皆曰天行。皆天道也。凡大象專以人事言。言天道強健不息。君子法之也。</p><p>初九。潛龍勿用。</p><p>九者老陽之數。動之所佔。潛隱也。陽息初復。一陽伏群陰之下。故曰潛。物莫神於龍。故借龍以喻陽氣。復子時當冬至。一陽初生。伏藏地下。故曰勿用。又卦位初為士。未出世之君子。德亦如是也。</p><h3 id="象曰-潛龍勿用。陽在下也。" tabindex="-1">象曰：潛龍勿用。陽在下也。 <a class="header-anchor" href="#象曰-潛龍勿用。陽在下也。" aria-label="Permalink to “象曰：潛龍勿用。陽在下也。”">​</a></h3><p>初陽伏在下。</p><p>九二。見龍在田。利見大人。</p><p>初二於三才為地。二在地上。故稱田。乾為大人。二雖不當位而居中。利見者。言大人宜於此時出見也。鄭康成謂利見九五之大人。非。五無應也。陽息至二臨。陽出地上。由潛而顯。大人亦如此也。</p><h3 id="象曰-見龍在田。德施普也。" tabindex="-1">象曰：見龍在田。德施普也。 <a class="header-anchor" href="#象曰-見龍在田。德施普也。" aria-label="Permalink to “象曰：見龍在田。德施普也。”">​</a></h3><p>德施普。言陽和之德。普及萬物也。</p><p>九三。君子終日乾乾。夕惕若。厲無咎。</p><p>乾為君子。為大明。故為日。晉順而麗乎大明。大明謂離日也。故乾亦為日。易林困之泰雲。陰雲四方。日在中央。以泰上坤為雲。下乾為日也。又蹇之鹹雲。日月並居。以鹹上兌為月。互乾為日。餘證尚多。皆詳焦氏易詁中。三居下卦之終。故曰終日。曰夕。惕。憂思也。厲危也。憂危故無咎。陽息至三泰。萬物思奮。人事亦如是。三四於三才為人爻。人居天地之中。宜乾惕有為也。厲許慎作夤。後易家多從之。而文言作厲。並以危釋厲義。注莫古於十翼。似當從也。</p><h3 id="象曰-終日乾乾。反覆道也。" tabindex="-1">象曰：終日乾乾。反覆道也。 <a class="header-anchor" href="#象曰-終日乾乾。反覆道也。" aria-label="Permalink to “象曰：終日乾乾。反覆道也。”">​</a></h3><p>乾盈則反巽。坤盈則復震。乾坤者震巽之終。震巽者乾坤之始。</p><p>九四。或躍在淵。無咎。</p><p>易林九家荀爽。皆以乾為江河。故乾亦為淵。躍。起也。四居上卦之下。故曰躍淵。或者。言事不一定。可則為之。慎審而行。故無咎也。陽息至四大壯。百果草木甲坼之時也。</p><h3 id="象曰-或躍在淵。進無咎也。" tabindex="-1">象曰：或躍在淵。進無咎也。 <a class="header-anchor" href="#象曰-或躍在淵。進無咎也。" aria-label="Permalink to “象曰：或躍在淵。進無咎也。”">​</a></h3><p>躍。釋文雲上也。初與四相上下。初潛淵底。故曰或躍在淵。言由初躍四也。時可進故無咎。</p><p>九五。飛龍在天。利見大人。</p><p>五於三才為天位。又為天子位。貴而得中。故曰飛龍在天。大人於此。居極尊之位。履萬物之上。嚮明而治。聖人作而萬物睹。故亦曰利見大人。九五陽息至五夬。萬物繁榮。相見之時也。</p><h3 id="象曰-飛龍在天。大人聚也。" tabindex="-1">象曰：飛龍在天。大人聚也。 <a class="header-anchor" href="#象曰-飛龍在天。大人聚也。" aria-label="Permalink to “象曰：飛龍在天。大人聚也。”">​</a></h3><p>五天位。故曰在天。聚原作造。釋文雲。劉歆父子皆作聚。聚與文言云從龍。風從虎義合。且向歆所據皆中秘古文。必無誤。故從之。</p><p>上九。亢龍有悔。</p><p>王肅曰。窮高曰亢。上九居卦之極。故曰窮。在六爻之上。故曰高，高則易危。窮則事盡。故有悔。按乾盈於巳。盈則虧。滿則損。乃天道之自然。太玄雲。成功者退。又中首次六雲。月闕其搏。不如開明於西。是其理也。</p><h3 id="象曰-亢龍有悔。盈不可久也。" tabindex="-1">象曰：亢龍有悔。盈不可久也。 <a class="header-anchor" href="#象曰-亢龍有悔。盈不可久也。" aria-label="Permalink to “象曰：亢龍有悔。盈不可久也。”">​</a></h3><p>陽在上乾盈。盈則必虧。故日不可久。</p><p>用九。見群龍無首。吉。</p><p>此文王以筮例示人也。易之本為六七八九。七九陽。八六陰。今遇陽胡以只言九。不言七。則以周易以九為用。與二易殊也。用者動也變也。用九者。言遇九則動。遇七則不動。若作用舍詁。則周易竟不用七八矣。不用七八。則揲蓍時常不遇九六。將何以為佔。蓋九六佔爻。七八佔彖之義。治易者十六七皆忽之。故其義常晦。見群龍無首吉者。申遇九則變之義也。九何以必變。陽之數九為極多。故曰群。陽極反陰。乃天地自然之理。乾為首。以陽剛居物首。易招物忌。變坤則無首。無首則能以柔濟剛。故吉。無。說文雲奇字。王育謂天屈西北為無。此節自古說者常有數蔽。見說吉即疑為佔辭。不知其申用九之義。一蔽也。見說群龍。即疑群龍指上六爻。不知其言九。二蔽也。見說群龍無首。即疑六爻全變。不知其指揲蓍之三變成一爻言。三蔽也。甚至以此為爻辭。四蔽也。籠統浮泛。銓釋乾健大義。五蔽也。豈知六十四卦。六爻之後。獨乾坤二卦。有此贅語者。誠以乾坤者陰陽。六十四卦。皆乾爻坤爻所積而成。乃乾卦只言九不言七。坤只言六不言八。不申明其故。揲蓍者胡所遵循。故於乾坤六爻之後。申曰用九用六。復恐人不解用九用六之義。又曰見群龍無首吉。利永貞也。其詳說皆在周易古筮考中。</p><h3 id="象曰-用九。天德不可為首也。" tabindex="-1">象曰：用九。天德不可為首也。 <a class="header-anchor" href="#象曰-用九。天德不可為首也。" aria-label="Permalink to “象曰：用九。天德不可為首也。”">​</a></h3><p>陽極則變。不變則剛柔不能相濟。兇之道也。故無首吉。</p><p>文言</p><p>此卦爻辭全為文王作之證也。彖傳申彖意。故曰彖曰。大象申卦義。小象申爻義。故曰象曰。此則合卦爻辭總述之。而制此乾坤之卦爻辭者。文王也。故曰文言。繹文王所言耳。仍彖曰象曰之例。並無其它深奧。乃劉獻曰。依文而言其理。故曰文言。姚信曰。乾坤為門戶。文說乾坤。六十二卦皆放焉。訖不得解。揆其因皆由王充馬融等。謂文王制卦辭。周公制爻辭。後儒惑其說。疑但言文王。或遺周公故也。</p><h3 id="曰元者善之長也。亨者嘉之會也。利者義之和也。貞者事之乾也。君子體仁足以長人。嘉會足以合禮。利物足以和義。貞固足以乾事。君子行此四德者。故曰乾元亨利貞。" tabindex="-1">曰元者善之長也。亨者嘉之會也。利者義之和也。貞者事之乾也。君子體仁足以長人。嘉會足以合禮。利物足以和義。貞固足以乾事。君子行此四德者。故曰乾元亨利貞。 <a class="header-anchor" href="#曰元者善之長也。亨者嘉之會也。利者義之和也。貞者事之乾也。君子體仁足以長人。嘉會足以合禮。利物足以和義。貞固足以乾事。君子行此四德者。故曰乾元亨利貞。" aria-label="Permalink to “曰元者善之長也。亨者嘉之會也。利者義之和也。貞者事之乾也。君子體仁足以長人。嘉會足以合禮。利物足以和義。貞固足以乾事。君子行此四德者。故曰乾元亨利貞。”">​</a></h3><p>李鼎祚雲。元為善長。故能體仁。仁主春生。東方木也。亨為嘉會。足以合禮。禮主夏養。南方火也。利為物宜。足以和義。義主秋成。西方金也。貞為事乾。以配於智。智主冬藏。北方水也。李氏此詁。最為透徹。與太玄罔直蒙酋冥理合。識周易真諦。蓋此八句。為最古之易說。梁武帝任釣臺謂為文王所言。固無根據。然穆姜即述之。可見其為舊說。故孔氏複述之。而歐陽公謂左氏著書。亦欲信今傳後。若本孔子之言。而以為穆姜。其誰傳信之。謂文言非孔子作。按左氏所紀古人言行。皆古人實有是言。有是行。而後紀之。非並無是事是言。盡左氏所造作也。觀穆姜述是語已曰。然因不可誣也。即謂古易說之可信。而不我欺也。且周易之興。至春秋已數百年。所傳古訓。必已多矣。然則穆姜述之。孔氏複述之。事之常耳。必謂甲述之為真。乙再述之即偽。似不然也。左氏非傳易者。其是否見十翼。未可知也。蓋文言皆雜採古易說。薈萃而成之。故此處以四德釋元亨利貞。下又曰元亨者。始而亨者也。利貞者性情也。又為二德。與前不同。顯為採集古說之證。不過古人質。不似後人之必曰某某雲耳。</p><h3 id="初九曰。潛龍勿用。何謂也。子曰。龍德而隱者也。不易乎世。不成乎名。遁世無悶。不見是而無悶。樂則行之。憂則違之。確乎其不可拔。潛龍也。" tabindex="-1">初九曰。潛龍勿用。何謂也。子曰。龍德而隱者也。不易乎世。不成乎名。遁世無悶。不見是而無悶。樂則行之。憂則違之。確乎其不可拔。潛龍也。 <a class="header-anchor" href="#初九曰。潛龍勿用。何謂也。子曰。龍德而隱者也。不易乎世。不成乎名。遁世無悶。不見是而無悶。樂則行之。憂則違之。確乎其不可拔。潛龍也。" aria-label="Permalink to “初九曰。潛龍勿用。何謂也。子曰。龍德而隱者也。不易乎世。不成乎名。遁世無悶。不見是而無悶。樂則行之。憂則違之。確乎其不可拔。潛龍也。”">​</a></h3><p>吳先生曰。易。當讀如論語丘不與易之易。按孟子易其田疇。趙歧雲。易。治也。初潛在下。與世無涉。故曰不易世。不成名。遁世無悶者。言甘於隱遁。不見是而無悶者。言人不知亦不慍也。樂則行。憂則否。緊決自守。利祿不能移。威武不能屈。故曰確乎其不可拔。莊子應帝王確乎能其事。注確堅也。</p><h3 id="九二曰。見龍在田。利見大人。何謂也。子曰。龍德而正中者也。庸言之信。庸行之謹。閒邪存其誠。善世而不伐。德博而化。易曰。見龍在田。利見大人。君德也。" tabindex="-1">九二曰。見龍在田。利見大人。何謂也。子曰。龍德而正中者也。庸言之信。庸行之謹。閒邪存其誠。善世而不伐。德博而化。易曰。見龍在田。利見大人。君德也。 <a class="header-anchor" href="#九二曰。見龍在田。利見大人。何謂也。子曰。龍德而正中者也。庸言之信。庸行之謹。閒邪存其誠。善世而不伐。德博而化。易曰。見龍在田。利見大人。君德也。" aria-label="Permalink to “九二曰。見龍在田。利見大人。何謂也。子曰。龍德而正中者也。庸言之信。庸行之謹。閒邪存其誠。善世而不伐。德博而化。易曰。見龍在田。利見大人。君德也。”">​</a></h3><p>二居下卦之中。故曰正中。庸言庸行中也。中則言必信。行必謹矣。閒邪使不入。則中不亂。存誠使不出。則中可守。善世中也。善世而伐。則偏而不中。不伐若己無所與者。則時中矣。人能如是。其德必博。而化必廣。二雖未升五為君乎。然君德已具。必升五也。</p><h3 id="九三曰。君子終日乾乾。夕惕若厲無咎。何謂也。子曰。君子進德修業。忠信所以進德也。修辭立其誠。所以居業也。知至至之。可與言幾也。知終終之。可與存義也。是故居上位而不驕。在下位而不憂。故乾乾因其時而惕。雖危無咎矣。" tabindex="-1">九三曰。君子終日乾乾。夕惕若厲無咎。何謂也。子曰。君子進德修業。忠信所以進德也。修辭立其誠。所以居業也。知至至之。可與言幾也。知終終之。可與存義也。是故居上位而不驕。在下位而不憂。故乾乾因其時而惕。雖危無咎矣。 <a class="header-anchor" href="#九三曰。君子終日乾乾。夕惕若厲無咎。何謂也。子曰。君子進德修業。忠信所以進德也。修辭立其誠。所以居業也。知至至之。可與言幾也。知終終之。可與存義也。是故居上位而不驕。在下位而不憂。故乾乾因其時而惕。雖危無咎矣。" aria-label="Permalink to “九三曰。君子終日乾乾。夕惕若厲無咎。何謂也。子曰。君子進德修業。忠信所以進德也。修辭立其誠。所以居業也。知至至之。可與言幾也。知終終之。可與存義也。是故居上位而不驕。在下位而不憂。故乾乾因其時而惕。雖危無咎矣。”">​</a></h3><p>修辭者立言也。誠者法則也。居者蓄也。積也。業以積而高大也。爻至三而極。其境至高。識其高而必達其境。故曰可與言幾。說文幾微也。系雲。幾者動之微。吉之先見者也。爻至三而終。其道已窮。識其窮而必赴之。故曰可與存義。義者宜也。</p><h3 id="九四曰。或躍在淵。無咎。何謂也。子曰。上下無常。非為邪也。進退無恆。非離群也。君子進德修業。欲及時也。故無咎。" tabindex="-1">九四曰。或躍在淵。無咎。何謂也。子曰。上下無常。非為邪也。進退無恆。非離群也。君子進德修業。欲及時也。故無咎。 <a class="header-anchor" href="#九四曰。或躍在淵。無咎。何謂也。子曰。上下無常。非為邪也。進退無恆。非離群也。君子進德修業。欲及時也。故無咎。" aria-label="Permalink to “九四曰。或躍在淵。無咎。何謂也。子曰。上下無常。非為邪也。進退無恆。非離群也。君子進德修業。欲及時也。故無咎。”">​</a></h3><p>欲及時用其學。以濟天下。故不避其嫌。四與初相上下。初潛四躍。初退四進。</p><h3 id="九五日。飛龍在天。利見大人。何謂也。子曰。同聲相應。同氣相求。水流溼。火就燥。雲從龍。風從虎。聖人作而萬物睹。本乎天者親上。本乎地者親下。則各從其類也。" tabindex="-1">九五日。飛龍在天。利見大人。何謂也。子曰。同聲相應。同氣相求。水流溼。火就燥。雲從龍。風從虎。聖人作而萬物睹。本乎天者親上。本乎地者親下。則各從其類也。 <a class="header-anchor" href="#九五日。飛龍在天。利見大人。何謂也。子曰。同聲相應。同氣相求。水流溼。火就燥。雲從龍。風從虎。聖人作而萬物睹。本乎天者親上。本乎地者親下。則各從其類也。" aria-label="Permalink to “九五日。飛龍在天。利見大人。何謂也。子曰。同聲相應。同氣相求。水流溼。火就燥。雲從龍。風從虎。聖人作而萬物睹。本乎天者親上。本乎地者親下。則各從其類也。”">​</a></h3><p>此與象辭之大人聚義同也。乾坤初爻交震巽。故曰同聲相應。上爻交艮兌。故曰同氣相求。中爻交坎離。故曰水流溼。火就燥。溼燥以方位言。荀爽謂坤溼乾燥者是也。坤原居北方。北方涸陰冱寒。故曰溼。乃乾自南往交坤成坎。故曰流溼。乾原居南方。南方炎熇焦灼。故曰燥。乃坤自北往交乾成離。故曰就燥。此於先天南北之乾坤。變為後天之離坎。至明白矣。乾若不在南。如何流北。坤若不在北。如何就南。故夫方位不明。易本立失。所關至巨。坤為雲。易林困之泰雲。陰雲四方。又未濟之升雲。雲興蔽日。皆以泰升上坤為雲。乾為龍。故曰云從龍。坤為風。易林訟之剝雲。烈風雨雪。大壯之剝雲。乘風駕雨。皆以剝下坤為風。陸績雲。風土氣也。巽坤之所生。故為風。按陸說是坤本為風也。乾為虎。故曰風從虎。風雲者陰。龍虎者陽。言陰必從陽也。乾虎之象。易林師之乾雲。三奸成虎。小畜之乾雲。東遇虎蛇。皆以乾為虎。此象昔儒無知者。後會稽茹敦和始發之。近師俞樾襲其說。謂虎陽物。君象。京虞以坤為虎。馬以兌為虎。皆不如九家以艮為虎之義長。艮何以為虎。以得乾之上爻。猶震得乾初亦為龍也。是乾本為虎也。故履革皆以乾為虎。說與易林闇合。聖人作者。乾為聖人。坤為萬物。聖人作而萬物睹。即比象也。仍陰從陽也。天地者陰陽。本乎天者親上。謂陽性上升順行。故乾二必上升坤五。以與陰類。本乎地者親下。謂陰性下降逆行。故坤五必下降乾二。以與陽類。故曰各從其類。陰陽相遇方為類。與朋友同。若陰遇陰陽通陽。則為敵矣。不朋不類也。頤六二曰。行失類也。以所遇皆陰。至明白也。乃由漢迄今。無有察覺者。</p><p>按此節舊解所以不明徹者。一由於類字義失。二由於乾虎。坤雲。坤風。象失。三由於不知此說陰陽相感之理。以著大人聚及利見之義。四由於不知此言先天象。故兩兩對舉。震巽對故相應。陰陽相應也。艮兌對故相求。陰陽相求也。水流溼。陽求陰。火就燥。陰求陽也。水火對也。雲從龍。風從虎。言陰陽不相離。乾坤對也。皆所以著陰陽類之理也。二千年以來。惟一茹敦和識虎為陰象之非。其功過荀虞遠矣。</p><p>又親上親下二語。使人識陰陽交之所以然也。親上者居上。親下者居下。則陰陽氣不交而為否矣。親上者居下。親下者居上。則陰陽氣接而為泰矣。各從其類。統相應相求各語而言之也。</p><h3 id="上九曰。亢龍有悔。何謂也。子曰。貴而無位。高而無民。賢人在下位而無輔。是以動而有悔也。" tabindex="-1">上九曰。亢龍有悔。何謂也。子曰。貴而無位。高而無民。賢人在下位而無輔。是以動而有悔也。 <a class="header-anchor" href="#上九曰。亢龍有悔。何謂也。子曰。貴而無位。高而無民。賢人在下位而無輔。是以動而有悔也。" aria-label="Permalink to “上九曰。亢龍有悔。何謂也。子曰。貴而無位。高而無民。賢人在下位而無輔。是以動而有悔也。”">​</a></h3><p>在上故貴。失正故無位。失位故無民。乾為賢人。既非九五之位則臣下也。三無應。故曰無輔。有此三因。故動而有侮。</p><h3 id="潛龍勿用。下也。見龍在田。時舍也。終日乾乾。行事也。或躍在淵。自試也。飛龍在天。上治也。亢龍有悔。窮之災也。乾元用九。天下治也。" tabindex="-1">潛龍勿用。下也。見龍在田。時舍也。終日乾乾。行事也。或躍在淵。自試也。飛龍在天。上治也。亢龍有悔。窮之災也。乾元用九。天下治也。 <a class="header-anchor" href="#潛龍勿用。下也。見龍在田。時舍也。終日乾乾。行事也。或躍在淵。自試也。飛龍在天。上治也。亢龍有悔。窮之災也。乾元用九。天下治也。" aria-label="Permalink to “潛龍勿用。下也。見龍在田。時舍也。終日乾乾。行事也。或躍在淵。自試也。飛龍在天。上治也。亢龍有悔。窮之災也。乾元用九。天下治也。”">​</a></h3><p>舍發也。詩舍失如破。易林家人之大有云。仲春孟夏。和氣所含。皆以舍為發。作捨棄者固非。以舍舒之葭（無草）字者亦非也。自試者試其可否。上治者居上治民。天下治申用九之故也。用九者剛變柔。言天下未治。治之以剛。若天下已治。則當濟以柔。明用九之故。因天下已治也。此治字與上治治字相呼應。後人因不識用九真諦。故籠統解說。多誤者。○王弼曰。此一章全以人事明之。</p><h3 id="潛龍勿用。陽氣潛藏。見龍在田。天下文明。終日乾乾。與時偕行。或躍在淵。乾道乃革。飛龍在天。乃位乎天德。亢龍有悔。與時偕極。乾元用九。乃見天則。" tabindex="-1">潛龍勿用。陽氣潛藏。見龍在田。天下文明。終日乾乾。與時偕行。或躍在淵。乾道乃革。飛龍在天。乃位乎天德。亢龍有悔。與時偕極。乾元用九。乃見天則。 <a class="header-anchor" href="#潛龍勿用。陽氣潛藏。見龍在田。天下文明。終日乾乾。與時偕行。或躍在淵。乾道乃革。飛龍在天。乃位乎天德。亢龍有悔。與時偕極。乾元用九。乃見天則。" aria-label="Permalink to “潛龍勿用。陽氣潛藏。見龍在田。天下文明。終日乾乾。與時偕行。或躍在淵。乾道乃革。飛龍在天。乃位乎天德。亢龍有悔。與時偕極。乾元用九。乃見天則。”">​</a></h3><p>王弼雲。此一章全以天氣明之。彖傳曰。時乘六龍以御天。即乾乘六陽時也。初乘子。陽氣雖生而未出。故曰潛藏。二乘寅。陽出地上。百物思奮。故曰文明。三乘辰。百果草木。長養興起。故曰與時偕行。四乘午。陽盈於巳。消於午。陰起用事。代有終。故曰乾道乃革。其以二上變成革為說者。非也。五乘申。百果草木。至秋成熟。乾德乃見。故曰位乎天德。廣雅位正也。言正當天德之時也。上乘戌。陽氣將盡矣。故曰與時偕極。陽極反陰。陰極反陽。乃天道之自然。故曰乾元用九。乃見天則。則者法也。一定之理也。</p><h3 id="乾元者始而亨者也。利貞者性情也。乾始能以美利利天下。不言所利。大矣哉。大哉乾乎。剛健中正。純粹精也。六爻發揮。旁通情也。時乘六龍。以御天也。雲行雨施。天下平也。" tabindex="-1">乾元者始而亨者也。利貞者性情也。乾始能以美利利天下。不言所利。大矣哉。大哉乾乎。剛健中正。純粹精也。六爻發揮。旁通情也。時乘六龍。以御天也。雲行雨施。天下平也。 <a class="header-anchor" href="#乾元者始而亨者也。利貞者性情也。乾始能以美利利天下。不言所利。大矣哉。大哉乾乎。剛健中正。純粹精也。六爻發揮。旁通情也。時乘六龍。以御天也。雲行雨施。天下平也。" aria-label="Permalink to “乾元者始而亨者也。利貞者性情也。乾始能以美利利天下。不言所利。大矣哉。大哉乾乎。剛健中正。純粹精也。六爻發揮。旁通情也。時乘六龍。以御天也。雲行雨施。天下平也。”">​</a></h3><p>性之與情。清惠棟阮元姚配中洪震烜胡縉諸儒說之。可謂詳盡矣。而利貞何以謂之性情。只以六爻正成既濟為說。無能瞭解者。則以自東漢以來。於利貞之真諦不明也。易林中孚之坤雲。符左契右。相與合齒。乾坤利貞。乳生六子。合齒者交也。即乾坤利貞也。蓋貞之為義屬冬。消息卦坤起午。至亥而為純坤。與原居亥之純乾相遇。陰牝陽。天地合德。陰陽和姤。萬物本以出生。故曰乾坤利貞。乳生六子。然則利貞之為和合明矣。故六十四卦言利貞者。二五無不交。否則卦體自相交。如中孚小過者也。彖傳曰。各正性命。保合太和。正易林所本也。且夫陽之喜陰。陰之喜陽。乃天地自然之性。本其性之所喜。以陽求陰。以陰承陽而和合焉。則由性而入於情矣。情者欲也。感也。利貞者性情。即謂陰之凝陽。變化和合。乃天地固有之性情。感之極正者也。崔覲雲。不雜曰純。不變曰粹。精者專一。極形容乾德之大。發揮者變動也。言六爻遇九六即變動也。旁玉篇雲。非一方也。通者感也。應也。陰陽相感故相通。繫辭雲。探賾索隱。鉤深致遠。又曰旁行而不流。皆謂正象之旁。尚有伏象。故曰索隱。曰鉤深。曰旁行。而震與巽相對。艮與兌相對。陰與陽絕異也。而文言曰同聲相應。同氣相求。蓋陰陽未合。有陰陽之分。陰陽既合。則和同混一而不分矣。故曰同。同則通。故易辭與易林用象。正伏常不分。而其所以能旁通之故。則仍陰陽相求相感固有之理。故曰旁通情也。時乘六龍義見前。雲行雨施。萬物亨通。故曰天下平。</p><h3 id="君子以成德為行。日可見之行也。潛之為言也。隱而未見。行而未成。是以君子弗用也。" tabindex="-1">君子以成德為行。日可見之行也。潛之為言也。隱而未見。行而未成。是以君子弗用也。 <a class="header-anchor" href="#君子以成德為行。日可見之行也。潛之為言也。隱而未見。行而未成。是以君子弗用也。" aria-label="Permalink to “君子以成德為行。日可見之行也。潛之為言也。隱而未見。行而未成。是以君子弗用也。”">​</a></h3><p>此言潛龍仍志在行道。與甘心隱遁鳴高者異。然而勿用者時未可也。夫子蓋恐山棲谷隱之流。執初爻為口實。故首以成德為行。明儒者之責任。舊解鮮有當者。俞樾雲。日為曰之訛。似當從之。</p><h3 id="君子學以聚之。問以辨之。寬以居之。仁以行之。易曰見龍在田。利見大人。君德也。" tabindex="-1">君子學以聚之。問以辨之。寬以居之。仁以行之。易曰見龍在田。利見大人。君德也。 <a class="header-anchor" href="#君子學以聚之。問以辨之。寬以居之。仁以行之。易曰見龍在田。利見大人。君德也。" aria-label="Permalink to “君子學以聚之。問以辨之。寬以居之。仁以行之。易曰見龍在田。利見大人。君德也。”">​</a></h3><p>寬博。居蓄也。言蓄德廣博也。君德既具。待升九五。則不惟居之。且行之矣。德者行之本。仁者行之用。</p><h3 id="九三。重剛而不中。上不在天。下不在田。故乾乾因其時而惕。雖危無咎矣。" tabindex="-1">九三。重剛而不中。上不在天。下不在田。故乾乾因其時而惕。雖危無咎矣。 <a class="header-anchor" href="#九三。重剛而不中。上不在天。下不在田。故乾乾因其時而惕。雖危無咎矣。" aria-label="Permalink to “九三。重剛而不中。上不在天。下不在田。故乾乾因其時而惕。雖危無咎矣。”">​</a></h3><p>君子終日乾乾夕惕若。是自朝及夕。無不乾惕也。故曰因時。所以然者。初二剛。三仍剛。故曰重剛。陽遇陽則窒。又卦以二五為中。三失中。上不及五。下不居二。故不敢自懈也。</p><h3 id="九四。重剛而不中。上不在天。下不在田。中不在人。故或之。或之者疑之也。故無咎。" tabindex="-1">九四。重剛而不中。上不在天。下不在田。中不在人。故或之。或之者疑之也。故無咎。 <a class="header-anchor" href="#九四。重剛而不中。上不在天。下不在田。中不在人。故或之。或之者疑之也。故無咎。" aria-label="Permalink to “九四。重剛而不中。上不在天。下不在田。中不在人。故或之。或之者疑之也。故無咎。”">​</a></h3><p>侯果日。下系雲。兼三才而兩之。謂兩爻為一才也。初兼二地也。三兼四人也。五兼六天也。四是兼才。非正。故言不在人。朱子疑四非重剛。豈知重剛與卦位無涉。乃謂上下爻也。疑則慎。慎故無咎。</p><h3 id="夫大人者。與天地合其德。與日月合其明。與四時合其序。與鬼神合其吉凶。先天而天弗違。後天而奉天時。天且弗違。而況於人乎。況於鬼神乎。" tabindex="-1">夫大人者。與天地合其德。與日月合其明。與四時合其序。與鬼神合其吉凶。先天而天弗違。後天而奉天時。天且弗違。而況於人乎。況於鬼神乎。 <a class="header-anchor" href="#夫大人者。與天地合其德。與日月合其明。與四時合其序。與鬼神合其吉凶。先天而天弗違。後天而奉天時。天且弗違。而況於人乎。況於鬼神乎。" aria-label="Permalink to “夫大人者。與天地合其德。與日月合其明。與四時合其序。與鬼神合其吉凶。先天而天弗違。後天而奉天時。天且弗違。而況於人乎。況於鬼神乎。”">​</a></h3><p>大人者五。五天位。二地位。上下昭列。尊卑判分。而五與二相往來。故與天地合其德。五坎位。坎月。二離位。離日。火為水妃。東西終始。故與日月合其明。夫天地日月。先天四中象也。惟大人能則之。元亨利貞。即春夏秋冬。四時之序。將來者進。成功者退。已用則賤。當時則貴。循環往來。不差不忒。故曰與四時合其序。夫震春離夏兌秋坎冬。即後天之四中象也。惟大人能兼之。消息卦。乾生於東。神也。坤死於西。鬼也。生則吉。死則兇。乃乾雖主生。不殺亦不能成歲功。故生死遞嬗。吉凶代更。亦惟大人能合之。先天之象。天地日月。牝牡雌雄。二儀肇分。法象自然如此。雖天亦不能違。後天之象。震兌坎離。互興迭廢。時而生。時而壯。時而老病死。人如此。物亦如此。天地亦如此。夫事而至於天不能違。人與鬼神。不待言矣。</p><h3 id="亢之為言也。知進而不知返。知存而不知亡。知得而不知喪。" tabindex="-1">亢之為言也。知進而不知返。知存而不知亡。知得而不知喪。 <a class="header-anchor" href="#亢之為言也。知進而不知返。知存而不知亡。知得而不知喪。" aria-label="Permalink to “亢之為言也。知進而不知返。知存而不知亡。知得而不知喪。”">​</a></h3><p>進也。存也。得也。陽之事也。退也。亡也。喪也。陰之事也。六者相對待。相循環。至上九亢極矣。極則宜變而知所返。懵不知返。故有悔也。按此專釋上九亢龍之義。兼申下文用九之故。知退即用九也。</p><h3 id="其唯聖人乎。知進退存亡。而不失其正者。其唯聖人乎。" tabindex="-1">其唯聖人乎。知進退存亡。而不失其正者。其唯聖人乎。 <a class="header-anchor" href="#其唯聖人乎。知進退存亡。而不失其正者。其唯聖人乎。" aria-label="Permalink to “其唯聖人乎。知進退存亡。而不失其正者。其唯聖人乎。”">​</a></h3><p>此專釋用九之故也。知進復知返。知存復知亡。故用九也。見群龍無首。即知退也。即陽變陰也。故夫用之為變。觀此而益明矣。自荀虞以來。不知此節系專釋用九之義。浮泛解釋。然文言此處舍用九不釋。是其辭未畢也。李鼎柞知此說用九。而以乾元用九。天下治也為解。仍不知知退知亡。即釋用九及無首之義。</p>',82)])])}const f=e(i,[["render",l]]);export{b as __pageData,f as default};
